ients'][$k]=$v;return true;} function get_transient($k){return isset($GLOBALS['wp_transients'][$k])?$GLOBALS['wp_transients'][$k]:false;} function delete_transient($k){unset($GLOBALS['wp_transients'][$k]);} function get_option($k,$d=false){return isset($GLOBALS['wp_options'][$k])?$GLOBALS['wp_options'][$k]:$d;} function update_option($k,$v,$autoload=null){if(in_array($k,(array)(isset($GLOBALS['fail_option_keys'])?$GLOBALS['fail_option_keys']:array()),true))return false;$GLOBALS['wp_options'][$k]=$v;return true;} function register_rest_route($ns,$route,$args){$GLOBALS['wp_routes'][]=array($ns,$route,$args);} function wp_parse_url($url){return parse_url($url);} function wp_http_validate_url($url){if(!is_string($url)||0!==strpos(strtolower($url),'https://'))return false;$host=parse_url($url,PHP_URL_HOST);if(!$host||in_array(strtolower($host),array('localhost'))||preg_match('/\.(localhost|local|internal|test)$/i',$host))return false;if(filter_var($host,FILTER_VALIDATE_IP)&&false===filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))return false;return $url;} function apply_filters($tag,$value){$args=func_get_args();array_shift($args);if(isset($GLOBALS['wp_filters'][$tag]))return call_user_func_array($GLOBALS['wp_filters'][$tag],$args);return $value;} function wp_remote_request($url,$args=array()){return new WP_Error('network_disabled','Tests must use a fake provider HTTP response.');} function wp_remote_retrieve_response_code($r){return isset($r['response']['code'])?$r['response']['code']:0;} function wp_remote_retrieve_body($r){return isset($r['body'])?$r['body']:'';} function wp_enqueue_script(){} function wp_enqueue_style(){} function rest_url($path=''){return 'https://cms.example.test/wp-json/'.$path;} function shortcode_atts($defaults,$atts){return array_merge($defaults,$atts);} function checked($a,$b,$echo=true){return $a===$b?'checked="checked"':'';} function selected($a,$b,$echo=true){return $a===$b?'selected="selected"':'';} 