function t_assert($cond,$msg){if(!$cond)throw new RuntimeException($msg);} function t_eq($a,$b,$msg='values differ'){if($a!==$b)throw new RuntimeException($msg.'; got '.var_export($a,true).' expected '.var_export($b,true));} function t_error($v,$code,$msg){t_assert(is_wp_error($v),$msg.' should be WP_Error');t_eq($v->get_error_code(),$code,$msg.' error code');}
function test_png($w=700,$h=520){$chunk=function($type,$data){return pack('N',strlen($data)).$type.$data.pack('N',crc32($type.$data));};$row="\0".str_repeat("\x80\x60\x40",$w);$raw=str_repeat($row,$h);return "\x89PNG\r\n\x1a\n".$chunk('IHDR',pack('NNCCCCC',$w,$h,8,2,0,0,0)).$chunk('IDAT',gzcompress($raw)).$chunk('IEND','');}
function valid_options($extra=array()){return array_merge(array('roomType'=>'kitchen','projectType'=>'new_installation','preferredStyle'=>'light_natural','customStyleDescription'=>'','woodSpecies'=>'oak','floorDirection'=>'parallel','finishPreference'=>'unsure','sheen'=>'matte','serviceCity'=>'','squareFootage'=>0),$extra);}
