function request_generate($file,$options=null){$r=new WP_REST_Request('POST','/rk-ai/v1/visualizer/flooring/generate');$r->files=array('image'=>array('tmp_name'=>$file,'error'=>0,'size'=>filesize($file)));$r->params['options']=json_encode(null===$options?valid_options():$options);return $r;}
